<main class="main"><header class="topbar"><div><div class="eyebrow">Biometric access intelligence / session history</div><h1>Access Sessions</h1><div class="subtitle">Session lifecycle, operator activity, and device usage history.</div></div><div class="live">● SESSION MONITOR</div></header>
<div class="section-head"><h2>Session overview</h2><span class="hint">Source · atomic_access.access_sessions</span></div><section class="stats">
<article class="stat"><div class="stat-label">Total sessions</div><div class="stat-value">{{ number_format($totalSessions) }}</div></article><article class="stat"><div class="stat-label">Active now</div><div class="stat-value green">{{ number_format($activeSessions) }}</div></article><article class="stat"><div class="stat-label">Orphaned · identity inactive</div><div class="stat-value amber">{{ number_format($orphanedSessions) }}</div></article><article class="stat"><div class="stat-label">Interrupted</div><div class="stat-value amber">{{ number_format($interruptedSessions) }}</div></article><article class="stat"><div class="stat-label">Completed</div><div class="stat-value cyan">{{ number_format($completedSessions) }}</div></article></section>
<div class="section-head"><h2>Session records</h2><span class="hint">{{ $sessions->total() }} matching records · newest first</span></div><section class="panel"><form class="filters" method="GET" action="{{ route('sessions.index') }}" style="padding:16px 16px 0"><input class="field search" type="search" name="q" value="{{ $filters['q'] ?? '' }}" placeholder="Search session ID, operator, device..."><select class="field" name="status" aria-label="Filter session status"><option value="">All statuses</option><option value="orphaned" @selected(($filters['status'] ?? '') === 'orphaned')>Orphaned · operator removed</option><option value="active" @selected(($filters['status'] ?? '') === 'active')>Active</option><option value="interrupted" @selected(($filters['status'] ?? '') === 'interrupted')>Interrupted</option><option value="completed" @selected(($filters['status'] ?? '') === 'completed')>Completed</option></select><input class="field" type="date" name="start_date" value="{{ $filters['start_date'] ?? '' }}" aria-label="Started from"><input class="field" type="date" name="end_date" value="{{ $filters['end_date'] ?? '' }}" aria-label="Started until"><button class="btn" type="submit">Apply filter</button><a class="btn secondary" href="{{ route('sessions.index') }}">Reset</a></form>
<div class="table-wrap"><table><thead><tr><th>Session</th><th>Operator</th><th>Device</th><th>Started at</th><th>Ended at</th><th>Duration</th><th>Status</th><th></th></tr></thead><tbody>
@forelse($sessions as $session)
<tr><td><div class="name">{{ \Illuminate\Support\Str::limit($session->session_id, 24) }}</div><div class="sub">Session ID</div></td><td><div class="name">{{ $session->operator_name ?: 'Unknown operator' }}</div><div class="sub">DB ID · {{ $session->operator_db_id ?: '—' }} · Device ID · {{ $session->device_operator_id ?: '—' }}</div></td><td><div class="name">{{ $session->device_name ?: $session->device_id }}</div><div class="sub">{{ $session->device_id }}</div></td><td>{{ $session->started_at ? \Illuminate\Support\Carbon::parse($session->started_at)->format('d M Y, H:i:s') : '—' }}</td><td>{{ $session->ended_at ? \Illuminate\Support\Carbon::parse($session->ended_at)->format('d M Y, H:i:s') : '—' }}</td><td>{{ $session->duration_seconds !== null ? intdiv((int) $session->duration_seconds, 3600) . 'h ' . intdiv((int) $session->duration_seconds % 3600, 60) . 'm' : ($session->display_status === 'active' ? 'In progress' : ($session->display_status === 'interrupted' ? 'Interrupted' : ($session->display_status === 'orphaned' ? 'Operator removed · not closed' : '—'))) }}</td><td><span class="status {{ $session->display_status === 'completed' ? 'completed' : ($session->display_status === 'interrupted' ? 'interrupted' : ($session->display_status === 'orphaned' ? 'orphaned' : '')) }}">{{ $session->display_status ?: 'unknown' }}</span></td><td><a class="detail-link" href="{{ route('sessions.show', $session->session_id) }}">View →</a></td></tr>
@empty<tr><td colspan="8" class="empty">No session records found. Session data will appear here when records are available in atomic_access.</td></tr>@endforelse
